sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* ════════════════════════════════════════
   SIDEBAR
════════════════════════════════════════ */
.dm-sidebar {
  width: 100%;
  height: 100vh;
  background: linear-gradient(160deg, #2d2669 0%, #4a3fa0 50%, #6b5fd4 100%);
  padding: 0;
  display: flex;
  flex-direction: column;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  position: sticky;
  top: 0;
  box-sizing: border-box;
  overflow: hidden;
}

.dm-sidebar::after {
  content: '';
  position: absolute; top: 0; right: 0;
  width: 1px; height: 100%;
  background: rgba(255,255,255,0.08);
  pointer-events: none;
}

/* ════════════════════════════════════════
   USER BLOCK — top
════════════════════════════════════════ */
.dm-user-block {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 30px 16px 18px;
  border-bottom: 1px solid rgba(255,255,255,0.10);
}

.dm-user-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  border: 1px solid rgba(255,255,255,0.22);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: rgba(255,255,255,0.80);
  font-size: 13px;
}

.dm-user-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.dm-user-name {
  font-size: 12px;
  font-weight: 600;
  color: rgba(255,255,255,0.90);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.dm-user-role {
  font-size: 10px;
  color: rgba(255,255,255,0.38);
  letter-spacing: 0.1px;
}

/* ════════════════════════════════════════
   MENU
════════════════════════════════════════ */
.dm-menu {
  list-style: none;
  padding: 12px 12px;
  margin: 0;
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
}

.dm-menu::-webkit-scrollbar { width: 0; }

.dm-menu li {
  margin-bottom: 2px;
}

.dm-menu a {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 12px;
  border-radius: 10px;
  text-decoration: none;
  font-size: 13px;
  font-weight: 500;
  color: rgba(255,255,255,0.70);
  transition:
    background .18s ease,
    color .18s ease,
    padding-left .18s ease;
}

.dm-menu a i {
  width: 20px;
  text-align: center;
  font-size: 14px;
  color: rgba(255,255,255,0.55);
  flex-shrink: 0;
  transition: color .18s ease, transform .18s ease;
}

.dm-menu li:not(.active) a:hover {
  background: rgba(255,255,255,0.10);
  color: #ffffff;
  padding-left: 15px;
}
.dm-menu li:not(.active) a:hover i {
  color: #ffffff;
  transform: scale(1.1);
}

.dm-menu li.active a {
  background: rgba(255,255,255,0.18);
  color: #ffffff;
  font-weight: 600;
  padding-left: 15px;
  box-shadow: inset 3px 0 0 rgba(255,255,255,0.90);
}
.dm-menu li.active a i {
  color: #ffffff;
}
